-- Mo Feng Blade installer (generated by build_installer.py - edit the source files instead).
--
-- 1. Import MoFengSword.fbx and MoFengVFX.fbx (or the .glb files) with the 3D Importer.
-- 2. Run this file once: Model tab > Run Script, or paste it into the Command Bar.
--
-- It builds the "Mo Feng Blade" Tool (StarterPack + a copy in ServerStorage), the
-- VFX assets, and the scripts. Running it again updates the scripts and keeps your Config.

-- Change this to resize the sword (and its effects): 0.8 = 20% smaller, 1.2 = 20% bigger.
local SWORD_SCALE = 1.0

local SOURCES = {}
SOURCES.Config = [=[
-- Mo Feng Blade settings. Lives in ReplicatedStorage.MoFengSword.Config.
-- Safe to edit: re-running the installer keeps an existing Config.

local Config = {}

-- "Cyan" (Mo Feng) or "Gold". A Tool can also override this with its "Theme" attribute.
Config.DefaultTheme = "Cyan"

Config.Themes = {
	Cyan = {
		Primary = Color3.fromRGB(0, 190, 255), -- aura, trails, crystal edges
		Core = Color3.fromRGB(205, 255, 255), -- hot centre of every effect
		Vein = Color3.fromRGB(40, 255, 235), -- glowing cracks, wisps
		Accent = Color3.fromRGB(140, 95, 255), -- gems
		Hilt = "Silver",
	},
	Gold = {
		Primary = Color3.fromRGB(255, 160, 25),
		Core = Color3.fromRGB(255, 246, 200),
		Vein = Color3.fromRGB(255, 205, 70),
		Accent = Color3.fromRGB(255, 90, 20),
		Hilt = "Gold",
	},
}

Config.Combat = {
	SwingCooldown = 0.38, -- seconds between clicks
	ComboReset = 1.0, -- idle time before the combo goes back to swing 1
	SwingDamage = { 12, 12, 18 }, -- per combo step
	HitDelay = 0.12, -- when the hitbox checks, after the click
	SwingRange = 7, -- hitbox depth in front of the player (studs)
	SwingWidth = 7,
	SwingHeight = 6,

	SpecialCooldown = 6,
	SpecialWindup = 0.35, -- charge time before the big slash lands
	SpecialDamage = 35,
	SpecialRange = 14,
	SpecialWidth = 16,

	DamageHumanoids = true, -- set false if your game handles damage itself (see SwordHit)
	FriendlyFire = false, -- with Teams, teammates can't hurt each other
}

-- Keys / buttons for the special attack (a touch button is added on mobile).
-- Right mouse is left out on purpose: Roblox uses it to turn the camera.
Config.SpecialInputs = { Enum.KeyCode.E, Enum.KeyCode.ButtonY }

-- Optional custom animations ("rbxassetid://123"). Leave empty to use Roblox's
-- built-in tool slash / lunge animations.
Config.Animations = {
	Swing = {}, -- e.g. { "rbxassetid://1", "rbxassetid://2", "rbxassetid://3" }
	Special = "",
}

-- Roll of the slash arc for each combo step (degrees). 90 = straight down.
Config.SlashAngles = { 70, -65, 95 }

Config.Sounds = {
	Equip = "rbxasset://sounds/unsheath.wav",
	Swing = "rbxasset://sounds/swordslash.wav",
	Special = "rbxasset://sounds/swordlunge.wav",
	Impact = "",
}

-- Paste uploaded image IDs here to override the textures that came with the import,
-- e.g. Glow = "rbxassetid://1234567". Keys: Glow Spark Star Ember Smoke Flash
-- RingSprite Wisp Beam Lightning Trail
Config.Textures = {}

-- Used when a texture is missing (built into every Roblox client).
Config.FallbackTextures = {
	Glow = "rbxasset://textures/particles/sparkles_main.dds",
	Smoke = "rbxasset://textures/particles/smoke_main.dds",
	Wisp = "rbxasset://textures/particles/fire_main.dds",
	Default = "rbxasset://textures/particles/sparkles_main.dds",
}

Config.VFX = {
	IdleRange = 140, -- idle extras (rocks, lightning) only run when the camera is this close
	OrbitRocks = 3,
	Lightning = true,
	ScreenFlash = true, -- special attack flash for players near the impact
	CameraShake = true, -- special attack shake for the attacker
	SlashRadius = 4.2, -- studs
	SpecialSlashRadius = 8,
	ShockwaveRadius = 16,
}

return Config
]=]
SOURCES.SwordVFX = [=[
-- Mo Feng Blade effects. Lives in ReplicatedStorage.MoFengSword.SwordVFX.
-- Clients play everything here; the server only calls ApplyTheme / ComputeImpact.

local Debris = game:GetService("Debris")
local Lighting = game:GetService("Lighting")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local Workspace = game:GetService("Workspace")

local Folder = script.Parent
local Config = require(Folder:WaitForChild("Config"))

local SwordVFX = {}

-- ---------------------------------------------------------------- lookups

local function assets()
	return Folder:FindFirstChild("Assets")
end

-- Returns the texture id for a key, and true when it had to use a built-in fallback.
function SwordVFX.Texture(key)
	local override = Config.Textures[key]
	if override and override ~= "" then
		return override, false
	end
	local a = assets()
	local id = a and a:GetAttribute("Tex_" .. key)
	if typeof(id) == "string" and id ~= "" then
		return id, false
	end
	return Config.FallbackTextures[key] or Config.FallbackTextures.Default, true
end

function SwordVFX.GetTheme(tool)
	local name = (tool and tool:GetAttribute("Theme")) or Config.DefaultTheme
	return Config.Themes[name] or Config.Themes[Config.DefaultTheme], name
end

-- Recolours everything tagged with a ColorRole attribute, refreshes textures
-- tagged with a TextureKey attribute, and swaps the hilt texture.
function SwordVFX.ApplyTheme(tool)
	local theme = SwordVFX.GetTheme(tool)
	for _, inst in ipairs(tool:GetDescendants()) do
		local key = inst:GetAttribute("TextureKey")
		if key and (inst:IsA("ParticleEmitter") or inst:IsA("Trail") or inst:IsA("Beam")) then
			local id, fallback = SwordVFX.Texture(key)
			inst.Texture = id
			if inst:IsA("ParticleEmitter") and inst:GetAttribute("Flipbook") then
				-- the built-in fallback isn't a 4x4 sheet, so only animate our own texture
				inst.FlipbookLayout = fallback and Enum.ParticleFlipbookLayout.None or Enum.ParticleFlipbookLayout.Grid4x4
			end
		end
		local role = inst:GetAttribute("ColorRole")
		if role then
			local c1 = theme[role] or theme.Primary
			local c2 = theme[inst:GetAttribute("ColorRole2") or role] or c1
			if inst:IsA("BasePart") or inst:IsA("Light") then
				inst.Color = c1
			elseif inst:IsA("ParticleEmitter") or inst:IsA("Trail") or inst:IsA("Beam") then
				inst.Color = ColorSequence.new(c1, c2)
			end
		end
	end
	local hilt = tool:FindFirstChild("Hilt")
	local a = assets()
	if hilt and hilt:IsA("MeshPart") and a then
		local id = a:GetAttribute(theme.Hilt == "Gold" and "Tex_HiltGold" or "Tex_HiltSilver")
		if typeof(id) == "string" and id ~= "" then
			hilt.TextureID = id
		end
	end
end

-- Where the special attack lands: on the ground a few studs in front of the player.
function SwordVFX.ComputeImpact(character)
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not root then
		return Vector3.zero
	end
	local ahead = root.Position + root.CFrame.LookVector * (Config.Combat.SpecialRange * 0.55)
	local ignore = { character }
	local fx = Workspace:FindFirstChild("MoFengFX")
	if fx then
		table.insert(ignore, fx)
	end
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	params.FilterDescendantsInstances = ignore
	local hit = Workspace:Raycast(ahead + Vector3.new(0, 4, 0), Vector3.new(0, -14, 0), params)
	return hit and hit.Position or (ahead - Vector3.new(0, 2.8, 0))
end

-- ---------------------------------------------------------------- helpers

local function ns(points)
	local keys = {}
	for _, p in ipairs(points) do
		table.insert(keys, NumberSequenceKeypoint.new(p[1], p[2]))
	end
	return NumberSequence.new(keys)
end

local function fxFolder()
	local f = Workspace:FindFirstChild("MoFengFX")
	if not f then
		f = Instance.new("Folder")
		f.Name = "MoFengFX"
		f.Parent = Workspace
	end
	return f
end

-- Runs step(t) every frame for `duration` seconds, t going 0 -> 1.
local function animate(duration, step)
	local start = os.clock()
	local conn
	conn = RunService.RenderStepped:Connect(function()
		local t = math.min(1, (os.clock() - start) / duration)
		local ok = pcall(step, t)
		if t >= 1 or not ok then
			conn:Disconnect()
		end
	end)
end

local function easeOut(t)
	return 1 - (1 - t) ^ 3
end

local function spawnAsset(name)
	local a = assets()
	local template = a and a:FindFirstChild(name)
	if not template then
		return nil
	end
	local part = template:Clone()
	part.Anchored = true
	part.CanCollide = false
	part.CanQuery = false
	part.CanTouch = false
	part.CastShadow = false
	part.Parent = fxFolder()
	return part, template.Size
end

-- Places a VFX mesh so its Blender axes line up with `frame` (X right, Y forward, Z normal).
local function placeInFrame(part, baseSize, frame, scale)
	local toLocal = part:GetAttribute("BlenderToLocal")
	if typeof(toLocal) ~= "CFrame" then
		toLocal = CFrame.identity
	end
	local pivot = part:GetAttribute("PivotOffset")
	if typeof(pivot) ~= "Vector3" then
		pivot = Vector3.zero
	end
	part.Size = baseSize * scale
	part.CFrame = frame * CFrame.new(-pivot * scale) * toLocal:Inverse()
end

local function emit(tool, name, count)
	for _, d in ipairs(tool:GetDescendants()) do
		if d.Name == name and d:IsA("ParticleEmitter") then
			d:Emit(count)
		end
	end
end

local function playSound(tool, name)
	local handle = tool:FindFirstChild("Handle")
	local sound = handle and handle:FindFirstChild(name)
	if sound and sound:IsA("Sound") and sound.SoundId ~= "" then
		sound:Play()
	end
end

local trailTokens = setmetatable({}, { __mode = "k" })

local function flashTrails(tool, duration)
	for _, d in ipairs(tool:GetDescendants()) do
		if d:IsA("Trail") then
			local token = (trailTokens[d] or 0) + 1
			trailTokens[d] = token
			d.Enabled = true
			task.delay(duration, function()
				if trailTokens[d] == token and d.Parent then
					d.Enabled = false
				end
			end)
		end
	end
end

local function pulseLight(tool, brightness, duration)
	local edge = tool:FindFirstChild("BladeEdge")
	local light = edge and edge:FindFirstChild("BladeLight")
	if not light then
		return
	end
	local base = light:GetAttribute("BaseBrightness") or light.Brightness
	light:SetAttribute("BaseBrightness", base)
	light.Brightness = brightness
	TweenService:Create(light, TweenInfo.new(duration, Enum.EasingStyle.Quad), { Brightness = base }):Play()
end

local function boostRates(tool, factor, duration)
	for _, d in ipairs(tool:GetDescendants()) do
		if d:IsA("ParticleEmitter") and (d:GetAttribute("BaseRate") or d.Rate) > 0 then
			local base = d:GetAttribute("BaseRate") or d.Rate
			d:SetAttribute("BaseRate", base)
			d.Rate = base * factor
			task.delay(duration, function()
				if d.Parent then
					d.Rate = base
				end
			end)
		end
	end
end

-- ---------------------------------------------------------------- building blocks

-- A crescent slash in front of the character. roll: degrees around the forward axis.
local function slash(character, theme, roll, radius, duration, travel)
	local root = character and character:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end
	local arc, arcSize = spawnAsset("SlashArc")
	local core, coreSize = spawnAsset("SlashCore")
	if arc then
		arc.Material = Enum.Material.ForceField
		arc.Color = theme.Primary
	end
	if core then
		core.Material = Enum.Material.Neon
		core.Color = theme.Core
	end
	local rcf = root.CFrame
	local base = CFrame.fromMatrix(rcf.Position + Vector3.new(0, 0.7, 0), rcf.RightVector, rcf.LookVector)
		* CFrame.Angles(0, math.rad(roll), 0)
	animate(duration, function(t)
		local e = easeOut(t)
		-- sweep the crescent around its centre so the thick head leads the swing
		local frame = base * CFrame.new(0, (travel or 0) * e, 0) * CFrame.Angles(0, 0, math.rad(35 - 50 * e))
		local s = radius * (0.78 + 0.32 * e)
		if arc then
			placeInFrame(arc, arcSize, frame, s)
			arc.Transparency = 0.05 + 0.95 * t ^ 1.6
		end
		if core then
			placeInFrame(core, coreSize, frame, s * 1.005)
			core.Transparency = math.min(1, t * 1.7)
		end
	end)
	if arc then
		Debris:AddItem(arc, duration + 0.1)
	end
	if core then
		Debris:AddItem(core, duration + 0.1)
	end
end

local function shards(origin, theme, count, speed, life)
	for i = 1, count do
		local part, size = spawnAsset(i % 2 == 0 and "Shard2" or "Shard1")
		if not part then
			return
		end
		part.Material = Enum.Material.Neon
		part.Color = theme.Core
		local dir = Vector3.new(math.random() - 0.5, math.random() * 0.8 - 0.1, math.random() - 0.5)
		dir = dir.Magnitude > 1e-3 and dir.Unit or Vector3.yAxis
		local spin = Vector3.new(math.random(), math.random(), math.random()) * 12
		part.Size = size * (0.8 + math.random() * 0.8)
		animate(life, function(t)
			local pos = origin + dir * speed * life * (1 - (1 - t) ^ 2) - Vector3.new(0, 4 * t * t, 0)
			part.CFrame = CFrame.new(pos) * CFrame.Angles(spin.X * t, spin.Y * t, spin.Z * t)
			part.Transparency = t * t
		end)
		Debris:AddItem(part, life + 0.1)
	end
end

local function newEmitter(parent, props)
	local e = Instance.new("ParticleEmitter")
	e.Enabled = false
	e.LightEmission = 1
	e.LightInfluence = 0
	for k, v in pairs(props) do
		e[k] = v
	end
	e.Parent = parent
	return e
end

-- Sparks, flash, embers and a light at a world position.
local function burstAt(position, theme, opts)
	local att = Instance.new("Attachment")
	att.Parent = Workspace.Terrain
	att.WorldPosition = position
	newEmitter(att, {
		Texture = SwordVFX.Texture("Spark"),
		Orientation = Enum.ParticleOrientation.VelocityParallel,
		Lifetime = NumberRange.new(0.25, 0.5),
		Speed = NumberRange.new(14, 26),
		SpreadAngle = Vector2.new(180, 180),
		Drag = 4,
		Acceleration = Vector3.new(0, -12, 0),
		Size = ns({ { 0, 0.28 }, { 1, 0 } }),
		Transparency = ns({ { 0, 0 }, { 1, 1 } }),
		Color = ColorSequence.new(theme.Core, theme.Primary),
	}):Emit(opts.sparks)
	newEmitter(att, {
		Texture = SwordVFX.Texture("Flash"),
		Lifetime = NumberRange.new(0.12, 0.16),
		Speed = NumberRange.new(0),
		Rotation = NumberRange.new(0, 360),
		Size = ns({ { 0, opts.flash * 0.4 }, { 0.3, opts.flash }, { 1, opts.flash * 1.1 } }),
		Transparency = ns({ { 0, 0 }, { 1, 1 } }),
		Color = ColorSequence.new(theme.Core),
		ZOffset = 1,
	}):Emit(1)
	newEmitter(att, {
		Texture = SwordVFX.Texture("Ember"),
		Lifetime = NumberRange.new(0.5, 1.0),
		Speed = NumberRange.new(3, 9),
		SpreadAngle = Vector2.new(180, 180),
		Drag = 2,
		Acceleration = Vector3.new(0, 3, 0),
		Size = ns({ { 0, 0.14 }, { 1, 0 } }),
		Transparency = ns({ { 0, 0 }, { 0.7, 0.2 }, { 1, 1 } }),
		Color = ColorSequence.new(theme.Vein, theme.Primary),
	}):Emit(opts.embers)
	local light = Instance.new("PointLight")
	light.Color = theme.Primary
	light.Range = opts.lightRange
	light.Brightness = opts.light
	light.Shadows = false
	light.Parent = att
	TweenService:Create(light, TweenInfo.new(0.4, Enum.EasingStyle.Quad), { Brightness = 0 }):Play()
	if Config.Sounds.Impact ~= "" then
		local s = Instance.new("Sound")
		s.SoundId = Config.Sounds.Impact
		s.Volume = 0.7
		s.Parent = att
		s:Play()
	end
	Debris:AddItem(att, 1.5)
end

-- Expanding ring. `frame` gives the ring plane (its Blender Z is the ring's normal).
local function ring(frame, theme, radius, duration, thick)
	local wave, waveSize = spawnAsset("ShockRing")
	local core, coreSize = spawnAsset("RingCore")
	if wave then
		wave.Material = Enum.Material.ForceField
		wave.Color = theme.Primary
	end
	if core then
		core.Material = Enum.Material.Neon
		core.Color = theme.Core
	end
	animate(duration, function(t)
		local s = math.max(0.05, radius * easeOut(t))
		if wave then
			placeInFrame(wave, waveSize, frame * CFrame.Angles(0, 0, t * 0.6), s)
			wave.Transparency = t ^ 1.5
		end
		if core then
			placeInFrame(core, coreSize, frame, s)
			core.Transparency = math.min(1, (thick and 0.1 or 0.35) + t * 1.2)
		end
	end)
	if wave then
		Debris:AddItem(wave, duration + 0.1)
	end
	if core then
		Debris:AddItem(core, duration + 0.1)
	end
end

local function groundFrame(position)
	return CFrame.fromMatrix(position + Vector3.new(0, 0.15, 0), Vector3.xAxis, -Vector3.zAxis)
end

local function cameraFrame(position)
	local cam = Workspace.CurrentCamera
	if not cam then
		return groundFrame(position)
	end
	local look = CFrame.lookAt(position, cam.CFrame.Position)
	return CFrame.fromMatrix(position, look.RightVector, look.UpVector)
end

local function screenFlash(theme)
	local cc = Instance.new("ColorCorrectionEffect")
	cc.Name = "MoFengFlash"
	cc.Brightness = 0.28
	cc.Contrast = 0.15
	cc.Saturation = 0.15
	cc.TintColor = Color3.new(1, 1, 1):Lerp(theme.Core, 0.6)
	cc.Parent = Lighting
	TweenService:Create(cc, TweenInfo.new(0.35, Enum.EasingStyle.Quad), {
		Brightness = 0,
		Contrast = 0,
		Saturation = 0,
		TintColor = Color3.new(1, 1, 1),
	}):Play()
	Debris:AddItem(cc, 0.4)
end

local shakeCount = 0

local function cameraShake(intensity, duration)
	shakeCount += 1
	local name = "MoFengShake" .. shakeCount
	local start = os.clock()
	RunService:BindToRenderStep(name, Enum.RenderPriority.Camera.Value + 1, function()
		local t = (os.clock() - start) / duration
		local cam = Workspace.CurrentCamera
		if t >= 1 or not cam then
			RunService:UnbindFromRenderStep(name)
			return
		end
		local a = intensity * (1 - t) ^ 2
		cam.CFrame = cam.CFrame
			* CFrame.Angles(math.rad((math.random() - 0.5) * a), math.rad((math.random() - 0.5) * a), 0)
	end)
end

-- ---------------------------------------------------------------- attacks

function SwordVFX.Swing(tool, combo)
	local character = tool.Parent
	if not (character and character:IsA("Model")) then
		return
	end
	local theme = SwordVFX.GetTheme(tool)
	flashTrails(tool, 0.3)
	emit(tool, "SwingSparks", 16)
	emit(tool, "Fragments", 6)
	playSound(tool, "SwingSound")
	pulseLight(tool, 3, 0.25)
	local roll = Config.SlashAngles[combo] or 70
	local radius = Config.VFX.SlashRadius * (combo == 3 and 1.15 or 1)
	task.delay(0.05, function()
		slash(character, theme, roll, radius, 0.24, 0.6)
	end)
	local edge = tool:FindFirstChild("BladeEdge")
	local tip = edge and edge:FindFirstChild("BladeTip")
	if tip then
		task.delay(0.1, function()
			shards(tip.WorldPosition, theme, 3, 9, 0.35)
		end)
	end
end

function SwordVFX.SpecialCharge(tool)
	local windup = Config.Combat.SpecialWindup
	boostRates(tool, 3, windup + 0.3)
	pulseLight(tool, 6, windup + 0.4)
	flashTrails(tool, windup + 0.45)
	emit(tool, "Crackle", 25)
	emit(tool, "TipGlint", 2)
end

function SwordVFX.SpecialRelease(tool, impact, isLocalAttacker)
	local character = tool.Parent
	if not (character and character:IsA("Model")) then
		return
	end
	local theme = SwordVFX.GetTheme(tool)
	impact = impact or SwordVFX.ComputeImpact(character)
	local radius = Config.VFX.SpecialSlashRadius
	slash(character, theme, 90, radius, 0.4, 6)
	task.delay(0.06, function()
		slash(character, theme, 65, radius * 0.8, 0.35, 4)
	end)
	emit(tool, "SwingSparks", 30)
	emit(tool, "Fragments", 14)
	playSound(tool, "SpecialSound")
	task.delay(0.12, function()
		local frame = groundFrame(impact)
		ring(frame, theme, Config.VFX.ShockwaveRadius, 0.55, true)
		task.delay(0.07, function()
			ring(frame, theme, Config.VFX.ShockwaveRadius * 0.6, 0.4, false)
		end)
		burstAt(impact + Vector3.new(0, 0.5, 0), theme, { sparks = 60, flash = 9, embers = 30, light = 8, lightRange = 24 })
		shards(impact + Vector3.new(0, 1, 0), theme, 10, 18, 0.6)
		local cam = Workspace.CurrentCamera
		if Config.VFX.ScreenFlash and cam and (cam.CFrame.Position - impact).Magnitude < 70 then
			screenFlash(theme)
		end
		if isLocalAttacker and Config.VFX.CameraShake then
			cameraShake(2.2, 0.35)
		end
	end)
end

function SwordVFX.Impact(position, themeName, isSpecial)
	local theme = Config.Themes[themeName] or Config.Themes[Config.DefaultTheme]
	burstAt(position, theme, {
		sparks = isSpecial and 30 or 16,
		flash = isSpecial and 4 or 2.2,
		embers = 8,
		light = 4,
		lightRange = 10,
	})
	ring(cameraFrame(position), theme, isSpecial and 4 or 2.2, 0.22, false)
end

-- ---------------------------------------------------------------- idle extras

local idleStates = {}

local function bolt(tool, edge, base, tip)
	local theme = SwordVFX.GetTheme(tool)
	local half = (tool:GetAttribute("BladeHalfWidth") or 0.28) * 1.1
	local across = base.CFrame.RightVector
	local a0, a1 = Instance.new("Attachment"), Instance.new("Attachment")
	local h0 = math.random()
	local h1 = math.clamp(h0 + (math.random() - 0.5) * 0.35, 0, 1)
	a0.Position = base.Position:Lerp(tip.Position, h0) + across * half * (math.random() < 0.5 and -1 or 1)
	a1.Position = base.Position:Lerp(tip.Position, h1) + across * half * (math.random() < 0.5 and -1 or 1)
	a0.Parent = edge
	a1.Parent = edge
	local beam = Instance.new("Beam")
	beam.Attachment0 = a0
	beam.Attachment1 = a1
	beam.Texture = SwordVFX.Texture("Lightning")
	beam.TextureMode = Enum.TextureMode.Stretch
	beam.TextureSpeed = 4
	beam.Width0 = 0.12
	beam.Width1 = 0.08
	beam.CurveSize0 = (math.random() - 0.5) * 1.2
	beam.CurveSize1 = (math.random() - 0.5) * 1.2
	beam.Segments = 12
	beam.FaceCamera = true
	beam.LightEmission = 1
	beam.LightInfluence = 0
	beam.Color = ColorSequence.new(theme.Core, theme.Vein)
	beam.Parent = edge
	task.delay(0.06, function()
		beam.Transparency = NumberSequence.new(0.45)
	end)
	for _, inst in ipairs({ beam, a0, a1 }) do
		Debris:AddItem(inst, 0.14)
	end
end

function SwordVFX.StartIdle(tool)
	if idleStates[tool] then
		return
	end
	local edge = tool:FindFirstChild("BladeEdge")
	local base = edge and edge:FindFirstChild("BladeBase")
	local tip = edge and edge:FindFirstChild("BladeTip")
	if not (base and tip) then
		return
	end
	local scale = tool:GetAttribute("SwordScale") or 1
	local state = { rocks = {}, nextBolt = os.clock() + 0.5, nextBurst = os.clock() + 1.5 }
	for i = 1, Config.VFX.OrbitRocks do
		local rock, size = spawnAsset("Rock" .. ((i - 1) % 3 + 1))
		if rock then
			rock.Size = size * scale * (0.8 + 0.4 * math.random())
			table.insert(state.rocks, {
				part = rock,
				phase = math.random() * math.pi * 2,
				speed = 0.8 + math.random() * 0.6,
				height = 0.25 + 0.6 * (i - 0.5) / Config.VFX.OrbitRocks,
				radius = (0.42 + math.random() * 0.15) * scale,
			})
		end
	end
	state.conn = RunService.RenderStepped:Connect(function()
		if not (tool.Parent and edge.Parent) then
			SwordVFX.StopIdle(tool)
			return
		end
		local now = os.clock()
		local p0, p1 = base.WorldPosition, tip.WorldPosition
		local cam = Workspace.CurrentCamera
		local near = cam ~= nil and (cam.CFrame.Position - p0).Magnitude < Config.VFX.IdleRange
		local axis = p1 - p0
		local len = axis.Magnitude
		if len < 1e-3 then
			return
		end
		axis /= len
		local width = base.WorldCFrame.RightVector
		local normal = width:Cross(axis)
		for _, r in ipairs(state.rocks) do
			if near then
				local a = now * r.speed + r.phase
				local pos = p0
					+ axis * (len * r.height + 0.06 * math.sin(now * 2 + r.phase))
					+ (width * math.cos(a) + normal * math.sin(a)) * r.radius
				r.part.CFrame = CFrame.new(pos) * CFrame.Angles(now * 0.9 + r.phase, now * 0.6, now * 0.4)
				r.part.Transparency = 0
			else
				r.part.Transparency = 1
			end
		end
		if not near then
			return
		end
		if Config.VFX.Lightning and now >= state.nextBolt then
			state.nextBolt = now + 0.6 + math.random() * 1.2
			bolt(tool, edge, base, tip)
		end
		if now >= state.nextBurst then
			state.nextBurst = now + 2.2 + math.random() * 2
			emit(tool, "Crackle", 8)
			emit(tool, "TipGlint", 1)
			pulseLight(tool, 2.6, 0.4)
		end
	end)
	idleStates[tool] = state
end

function SwordVFX.StopIdle(tool)
	local state = idleStates[tool]
	if not state then
		return
	end
	idleStates[tool] = nil
	if state.conn then
		state.conn:Disconnect()
	end
	for _, r in ipairs(state.rocks) do
		r.part:Destroy()
	end
end

return SwordVFX
]=]
SOURCES.Server = [=[
-- Mo Feng Blade server: hit detection, damage, cooldowns, and telling other
-- players to play the effects. Lives in ServerScriptService.
--
-- Hook it into your game: ReplicatedStorage.MoFengSword.SwordHit (BindableEvent)
-- fires (attackerPlayer, hitInstance, damage, isSpecial) for every hit. Tag any
-- part or model "MoFengHittable" (e.g. balloons) to make the sword hit it too.

local CollectionService = game:GetService("CollectionService")
local Debris = game:GetService("Debris")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace = game:GetService("Workspace")

local Folder = ReplicatedStorage:WaitForChild("MoFengSword")
local Config = require(Folder:WaitForChild("Config"))
local SwordVFX = require(Folder:WaitForChild("SwordVFX"))
local Remote = Folder:WaitForChild("Remote")
local SwordHit = Folder:WaitForChild("SwordHit")

local TAG = "MoFengSword"
local HITTABLE = "MoFengHittable"

-- ---------------------------------------------------------------- tool setup

local setUp = setmetatable({}, { __mode = "k" })

local function setupTool(tool)
	if setUp[tool] or not tool:IsA("Tool") then
		return
	end
	setUp[tool] = true
	local handle = tool:FindFirstChild("Handle")
	if handle then
		-- make sure every mesh is welded (the installer does this, but be safe)
		local welded = { [handle] = true }
		for _, w in ipairs(tool:GetDescendants()) do
			if w:IsA("WeldConstraint") or w:IsA("Weld") then
				if w.Part0 then
					welded[w.Part0] = true
				end
				if w.Part1 then
					welded[w.Part1] = true
				end
			end
		end
		for _, part in ipairs(tool:GetDescendants()) do
			if part:IsA("BasePart") then
				part.Anchored = false
				part.CanCollide = false
				part.Massless = true
				if not welded[part] then
					local w = Instance.new("WeldConstraint")
					w.Part0 = handle
					w.Part1 = part
					w.Parent = handle
				end
			end
		end
	end
	SwordVFX.ApplyTheme(tool)
	tool:GetAttributeChangedSignal("Theme"):Connect(function()
		SwordVFX.ApplyTheme(tool)
	end)
end

CollectionService:GetInstanceAddedSignal(TAG):Connect(setupTool)
for _, tool in ipairs(CollectionService:GetTagged(TAG)) do
	setupTool(tool)
end

-- ---------------------------------------------------------------- combat

local state = {}

Players.PlayerRemoving:Connect(function(player)
	state[player] = nil
end)

local function equippedSword(player)
	local character = player.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	if not humanoid or humanoid.Health <= 0 then
		return nil
	end
	for _, child in ipairs(character:GetChildren()) do
		if child:IsA("Tool") and CollectionService:HasTag(child, TAG) then
			return child, character
		end
	end
	return nil
end

local function fireOthers(player, ...)
	for _, other in ipairs(Players:GetPlayers()) do
		if other ~= player then
			Remote:FireClient(other, ...)
		end
	end
end

-- Roblox's default Animate script plays its tool slash / lunge when it sees this value.
local function playToolAnim(tool, name)
	if name == "Slash" and #Config.Animations.Swing > 0 then
		return
	end
	if name == "Lunge" and Config.Animations.Special ~= "" then
		return
	end
	local value = Instance.new("StringValue")
	value.Name = "toolanim"
	value.Value = name
	value.Parent = tool
	Debris:AddItem(value, 2)
end

local function sameTeam(a, b)
	if Config.Combat.FriendlyFire or not (a and b) then
		return false
	end
	return a.Team ~= nil and a.Team == b.Team and not a.Neutral
end

local function doHits(player, character, tool, isSpecial, combo)
	local root = character:FindFirstChild("HumanoidRootPart")
	if not root or tool.Parent ~= character then
		return
	end
	local c = Config.Combat
	local depth = isSpecial and c.SpecialRange or c.SwingRange
	local size = isSpecial and Vector3.new(c.SpecialWidth, 9, depth) or Vector3.new(c.SwingWidth, c.SwingHeight, depth)
	local box = root.CFrame * CFrame.new(0, 0.5, -depth / 2)
	local params = OverlapParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	params.FilterDescendantsInstances = { character }
	local damage = isSpecial and c.SpecialDamage or (c.SwingDamage[combo] or c.SwingDamage[1])
	local themeName = tool:GetAttribute("Theme") or Config.DefaultTheme
	local hitModels, hitThings = {}, {}
	for _, part in ipairs(Workspace:GetPartBoundsInBox(box, size, params)) do
		local model = part:FindFirstAncestorOfClass("Model")
		local humanoid = model and model:FindFirstChildOfClass("Humanoid")
		if humanoid then
			if not hitModels[model] and humanoid.Health > 0 then
				hitModels[model] = true
				local victim = Players:GetPlayerFromCharacter(model)
				if not sameTeam(player, victim) then
					if c.DamageHumanoids then
						humanoid:TakeDamage(damage)
					end
					local target = model:FindFirstChild("HumanoidRootPart") or part
					Remote:FireAllClients("Impact", target.Position, themeName, isSpecial)
					SwordHit:Fire(player, model, damage, isSpecial)
				end
			end
		else
			local thing = CollectionService:HasTag(part, HITTABLE) and part
				or (model and CollectionService:HasTag(model, HITTABLE) and model)
			if thing and not hitThings[thing] then
				hitThings[thing] = true
				Remote:FireAllClients("Impact", part.Position, themeName, isSpecial)
				SwordHit:Fire(player, thing, damage, isSpecial)
			end
		end
	end
end

Remote.OnServerEvent:Connect(function(player, action, combo)
	local tool, character = equippedSword(player)
	if not tool then
		return
	end
	local st = state[player]
	if not st then
		st = { lastSwing = 0, lastSpecial = -math.huge }
		state[player] = st
	end
	local now = os.clock()
	if action == "Swing" then
		-- a little leeway for network jitter
		if now - st.lastSwing < Config.Combat.SwingCooldown * 0.8 then
			return
		end
		st.lastSwing = now
		combo = math.floor(tonumber(combo) or 1)
		if combo ~= combo then
			combo = 1
		end
		combo = math.clamp(combo, 1, 3)
		playToolAnim(tool, "Slash")
		fireOthers(player, "Swing", tool, combo)
		task.delay(Config.Combat.HitDelay, function()
			doHits(player, character, tool, false, combo)
		end)
	elseif action == "Special" then
		if now - st.lastSpecial < Config.Combat.SpecialCooldown * 0.9 then
			return
		end
		st.lastSpecial = now
		fireOthers(player, "SpecialCharge", tool)
		task.delay(Config.Combat.SpecialWindup, function()
			if tool.Parent ~= character then
				return
			end
			playToolAnim(tool, "Lunge")
			fireOthers(player, "SpecialRelease", tool, SwordVFX.ComputeImpact(character))
			doHits(player, character, tool, true, 1)
		end)
	end
end)
]=]
SOURCES.Client = [=[
-- Mo Feng Blade client: input for your own sword, and effects for every sword
-- in the server. Lives in StarterPlayer.StarterPlayerScripts.

local CollectionService = game:GetService("CollectionService")
local ContextActionService = game:GetService("ContextActionService")
local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local Workspace = game:GetService("Workspace")

local player = Players.LocalPlayer
local Folder = ReplicatedStorage:WaitForChild("MoFengSword")
local Config = require(Folder:WaitForChild("Config"))
local SwordVFX = require(Folder:WaitForChild("SwordVFX"))
local Remote = Folder:WaitForChild("Remote")

local TAG = "MoFengSword"
local SPECIAL_ACTION = "MoFengSpecial"
local FIRST_PERSON = "MoFengFirstPerson"

local equipped = nil
local combo, lastSwing, lastSpecial = 0, 0, -math.huge
local animCache = {}

-- ---------------------------------------------------------------- your sword

local function playCustomAnimation(id)
	if not id or id == "" then
		return
	end
	local character = player.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
	if not animator then
		return
	end
	local track = animCache[id]
	if not track then
		local anim = Instance.new("Animation")
		anim.AnimationId = id
		track = animator:LoadAnimation(anim)
		animCache[id] = track
	end
	track:Play(0.05)
end

local function swing()
	local tool = equipped
	if not tool then
		return
	end
	local now = os.clock()
	if now - lastSwing < Config.Combat.SwingCooldown then
		return
	end
	combo = (now - lastSwing > Config.Combat.ComboReset) and 1 or (combo % 3 + 1)
	lastSwing = now
	playCustomAnimation(Config.Animations.Swing[combo])
	SwordVFX.Swing(tool, combo)
	Remote:FireServer("Swing", combo)
end

local function special(_, inputState)
	if inputState ~= Enum.UserInputState.Begin then
		return Enum.ContextActionResult.Pass
	end
	local tool = equipped
	if not tool then
		return Enum.ContextActionResult.Pass
	end
	local now = os.clock()
	if now - lastSpecial < Config.Combat.SpecialCooldown then
		return Enum.ContextActionResult.Sink
	end
	lastSpecial = now
	SwordVFX.SpecialCharge(tool)
	Remote:FireServer("Special")
	task.delay(Config.Combat.SpecialWindup, function()
		if equipped == tool then
			playCustomAnimation(Config.Animations.Special)
			SwordVFX.SpecialRelease(tool, nil, true)
		end
	end)
	return Enum.ContextActionResult.Sink
end

local hooked = setmetatable({}, { __mode = "k" })

local function hookTool(tool)
	if hooked[tool] or not tool:IsA("Tool") or not CollectionService:HasTag(tool, TAG) then
		return
	end
	hooked[tool] = true
	tool.Equipped:Connect(function()
		equipped = tool
		ContextActionService:BindAction(SPECIAL_ACTION, special, true, table.unpack(Config.SpecialInputs))
		ContextActionService:SetTitle(SPECIAL_ACTION, "Special")
		ContextActionService:SetPosition(SPECIAL_ACTION, UDim2.new(1, -150, 1, -150))
		-- keep the sword visible in first person (Roblox hides the character there)
		local parts = {}
		for _, d in ipairs(tool:GetDescendants()) do
			if d:IsA("BasePart") then
				table.insert(parts, d)
			end
		end
		RunService:BindToRenderStep(FIRST_PERSON, Enum.RenderPriority.Camera.Value + 2, function()
			for _, p in ipairs(parts) do
				p.LocalTransparencyModifier = 0
			end
		end)
		local handle = tool:FindFirstChild("Handle")
		local sound = handle and handle:FindFirstChild("EquipSound")
		if sound and sound.SoundId ~= "" then
			sound:Play()
		end
	end)
	tool.Unequipped:Connect(function()
		if equipped == tool then
			equipped = nil
		end
		ContextActionService:UnbindAction(SPECIAL_ACTION)
		RunService:UnbindFromRenderStep(FIRST_PERSON)
	end)
	tool.Activated:Connect(swing)
end

local function watch(container)
	for _, child in ipairs(container:GetChildren()) do
		hookTool(child)
	end
	container.ChildAdded:Connect(hookTool)
end

player.ChildAdded:Connect(function(child)
	if child:IsA("Backpack") then
		watch(child)
	end
end)
local backpack = player:FindFirstChildOfClass("Backpack")
if backpack then
	watch(backpack)
end
player.CharacterAdded:Connect(function(character)
	-- dying with the sword out doesn't always fire Unequipped, so reset here
	equipped = nil
	animCache = {}
	ContextActionService:UnbindAction(SPECIAL_ACTION)
	pcall(function()
		RunService:UnbindFromRenderStep(FIRST_PERSON)
	end)
	watch(character)
end)
if player.Character then
	watch(player.Character)
end

-- ---------------------------------------------------------------- every sword

local tracked = setmetatable({}, { __mode = "k" })

local function updateIdle(tool)
	local holder = tool.Parent
	local held = holder ~= nil
		and holder:IsA("Model")
		and holder:FindFirstChildOfClass("Humanoid") ~= nil
		and tool:IsDescendantOf(Workspace)
	if held then
		SwordVFX.StartIdle(tool)
	else
		SwordVFX.StopIdle(tool)
	end
end

local function trackSword(tool)
	if tracked[tool] or not tool:IsA("Tool") then
		return
	end
	tracked[tool] = true
	updateIdle(tool)
	tool.AncestryChanged:Connect(function()
		updateIdle(tool)
	end)
end

CollectionService:GetInstanceAddedSignal(TAG):Connect(trackSword)
CollectionService:GetInstanceRemovedSignal(TAG):Connect(function(tool)
	SwordVFX.StopIdle(tool)
end)
for _, tool in ipairs(CollectionService:GetTagged(TAG)) do
	trackSword(tool)
end

-- effects for other players' swords, and hit impacts for everyone
Remote.OnClientEvent:Connect(function(action, a, b, c)
	if action == "Impact" and typeof(a) == "Vector3" then
		SwordVFX.Impact(a, b, c)
	elseif typeof(a) == "Instance" and a:IsA("Tool") then
		if action == "Swing" then
			SwordVFX.Swing(a, b)
		elseif action == "SpecialCharge" then
			SwordVFX.SpecialCharge(a)
		elseif action == "SpecialRelease" then
			SwordVFX.SpecialRelease(a, b, false)
		end
	end
end)
]=]
local LAYOUT = {
	swordScale = SWORD_SCALE,
	points = {
		BladeBase = { 0, 0, 0.8 },
		BladeTip = { 0, 0, 3.21 },
		BladeMid = { 0, 0, 1.9 },
		FlowStart = { 0, 0, 0.85 },
		FlowEnd = { 0, 0, 3.05 },
		GuardCenter = { 0, 0, 0.42 },
		Pommel = { 0, 0, -1.1 },
		Grip = { 0, 0, -0.47 },
		BladeHalfWidth = 0.285,
		BladeHalfThickness = 0.06,
	},
	pivots = {
		SlashArc = { -0.0, -0.3706, -0.0 },
		SlashCore = { -0.0, -0.3706, -0.003 },
	},
	textureKeys = { "Glow", "Spark", "Star", "Ember", "Smoke", "Flash", "RingSprite", "Wisp", "Beam", "Lightning", "Trail", "HiltGold" },
	vfxAssets = { "SlashArc", "SlashCore", "ShockRing", "RingCore", "Shard1", "Shard2", "Rock1", "Rock2", "Rock3" },
}

local ChangeHistoryService = game:GetService("ChangeHistoryService")
local CollectionService = game:GetService("CollectionService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Selection = game:GetService("Selection")
local ServerScriptService = game:GetService("ServerScriptService")
local ServerStorage = game:GetService("ServerStorage")
local StarterPack = game:GetService("StarterPack")
local StarterPlayer = game:GetService("StarterPlayer")
local Workspace = game:GetService("Workspace")

local TOOL_NAME = "Mo Feng Blade"
local TAG = "MoFengSword"
local SWORD_PARTS = { "Handle", "Hilt", "BladeCore", "BladeEdge", "BladeRunes", "EnergyVeins", "AccentGems", "BladeAura" }
local NEON_ROLES = { BladeEdge = "Primary", BladeRunes = "Core", EnergyVeins = "Vein", AccentGems = "Accent" }
local TEXTURED = { "Handle", "Hilt", "BladeCore" }

local notes = {}
local function note(msg)
	table.insert(notes, msg)
	warn("[Mo Feng] " .. msg)
end

local recording
pcall(function()
	recording = ChangeHistoryService:TryBeginRecording("Install Mo Feng Blade")
end)

-- ---------------------------------------------------------------- finding the imports

local function findImport(name)
	for _, inst in ipairs(Selection:Get()) do
		if inst.Name == name then
			return inst
		end
	end
	for _, inst in ipairs(Workspace:GetDescendants()) do
		if inst.Name == name and (inst:IsA("Model") or inst:IsA("Folder")) then
			return inst
		end
	end
	return nil
end

local function findPart(root, name)
	local exact = root:FindFirstChild(name, true)
	if exact and exact:IsA("BasePart") then
		return exact
	end
	for _, d in ipairs(root:GetDescendants()) do
		if d:IsA("BasePart") and d.Name:sub(1, #name) == name then
			return d
		end
	end
	return nil
end

-- The exports carry three tiny marker cubes at Blender (0,0,0), (0,1,0), (0,0,1).
-- They tell us exactly how the importer scaled and rotated the file.
local function markerFrame(model)
	local o, y, z = findPart(model, "Mark_O"), findPart(model, "Mark_Y"), findPart(model, "Mark_Z")
	assert(o and y and z, model.Name .. ": the Mark_O / Mark_Y / Mark_Z marker parts are missing (re-import the file)")
	local origin = o.Position
	local yv, zv = y.Position - origin, z.Position - origin
	local xu = yv.Unit:Cross(zv.Unit)
	return { O = origin, X = xu, Y = yv.Unit, Z = zv.Unit, k = zv.Magnitude, markers = { o, y, z } }
end

local function toWorld(f, p)
	return f.O + (f.X * p[1] + f.Y * p[2] + f.Z * p[3]) * f.k
end

local function textureOf(part)
	if part:IsA("MeshPart") and part.TextureID ~= "" then
		return part.TextureID
	end
	local sa = part:FindFirstChildOfClass("SurfaceAppearance")
	if sa then
		local ok, id = pcall(function()
			return sa.ColorMap
		end)
		if ok and typeof(id) == "string" and id ~= "" then
			return id
		end
		ok, id = pcall(function()
			return sa.ColorMapContent.Uri
		end)
		if ok and typeof(id) == "string" and id ~= "" then
			return id
		end
	end
	return ""
end

local function clearSurfaceAppearance(part)
	for _, child in ipairs(part:GetChildren()) do
		if child:IsA("SurfaceAppearance") then
			child:Destroy()
		end
	end
end

-- Keep the imported texture, but as TextureID (scripts can swap it for the gold theme).
local function useTextureID(part, label)
	local id = textureOf(part)
	clearSurfaceAppearance(part)
	if part:IsA("MeshPart") and id ~= "" then
		part.TextureID = id
	elseif id == "" then
		note(label .. " came in without its texture; set its TextureID to the matching PNG from the textures folder")
	end
	return id
end

local function stripTexture(part)
	clearSurfaceAppearance(part)
	if part:IsA("MeshPart") then
		part.TextureID = ""
	end
end

local function make(className, props, parent)
	local inst = Instance.new(className)
	for k, v in pairs(props) do
		if k ~= "Attributes" then
			inst[k] = v
		end
	end
	for k, v in pairs(props.Attributes or {}) do
		inst:SetAttribute(k, v)
	end
	inst.Parent = parent
	return inst
end

local function ns(points)
	local keys = {}
	for _, p in ipairs(points) do
		table.insert(keys, NumberSequenceKeypoint.new(p[1], p[2]))
	end
	return NumberSequence.new(keys)
end

local function upsert(parent, className, name)
	local existing = parent:FindFirstChild(name)
	if existing and existing.ClassName == className then
		return existing
	end
	if existing then
		existing:Destroy()
	end
	return make(className, { Name = name }, parent)
end

local function upsertScript(parent, className, name, source, keepExisting)
	local existing = parent:FindFirstChild(name)
	if existing and keepExisting and existing:IsA(className) then
		return existing
	end
	if existing then
		existing:Destroy()
	end
	local s = Instance.new(className)
	s.Name = name
	s.Source = source
	s.Parent = parent
	return s
end

-- ---------------------------------------------------------------- scripts

local folder = upsert(ReplicatedStorage, "Folder", "MoFengSword")
local configModule = upsertScript(folder, "ModuleScript", "Config", SOURCES.Config, true)
upsertScript(folder, "ModuleScript", "SwordVFX", SOURCES.SwordVFX, false)
upsert(folder, "RemoteEvent", "Remote")
upsert(folder, "BindableEvent", "SwordHit")
local assetsFolder = upsert(folder, "Folder", "Assets")
upsertScript(ServerScriptService, "Script", "MoFengSwordServer", SOURCES.Server, false)
local playerScripts = StarterPlayer:FindFirstChildOfClass("StarterPlayerScripts")
	or make("StarterPlayerScripts", { Name = "StarterPlayerScripts" }, StarterPlayer)
upsertScript(playerScripts, "LocalScript", "MoFengSwordClient", SOURCES.Client, false)

local okConfig, Config = pcall(require, configModule)
if not okConfig then
	note("Config has an error, using defaults for the install: " .. tostring(Config))
	Config = { DefaultTheme = "Cyan", Sounds = {}, FallbackTextures = {} }
end

-- ---------------------------------------------------------------- VFX assets

local vfxModel = findImport("MoFengVFX")
if vfxModel then
	assetsFolder:ClearAllChildren()
	for key in pairs(assetsFolder:GetAttributes()) do
		assetsFolder:SetAttribute(key, nil)
	end
	local f = markerFrame(vfxModel)
	local toBlender = CFrame.fromMatrix(Vector3.zero, f.X, f.Y)
	local found = 0
	for _, key in ipairs(LAYOUT.textureKeys) do
		local carrier = findPart(vfxModel, "Tex_" .. key)
		local id = carrier and textureOf(carrier) or ""
		if id ~= "" then
			assetsFolder:SetAttribute("Tex_" .. key, id)
			found += 1
		end
	end
	if found < #LAYOUT.textureKeys then
		note(("only %d of %d VFX textures came in with the import; missing ones use Roblox's built-in sparkle"):format(
			found,
			#LAYOUT.textureKeys
		))
	end
	for _, name in ipairs(LAYOUT.vfxAssets) do
		local part = findPart(vfxModel, name)
		if part then
			if name == "SlashArc" or name == "ShockRing" or name:sub(1, 4) == "Rock" then
				useTextureID(part, name)
			else
				stripTexture(part)
			end
			part.Size = part.Size / f.k -- 1 Blender unit = 1 stud
			part:SetAttribute("BlenderToLocal", part.CFrame.Rotation:Inverse() * toBlender)
			local pivot = LAYOUT.pivots[name]
			if pivot then
				part:SetAttribute("PivotOffset", Vector3.new(pivot[1], pivot[2], pivot[3]))
			end
			part.Material = (name == "SlashArc" or name == "ShockRing") and Enum.Material.ForceField
				or (name:sub(1, 4) == "Rock" and Enum.Material.SmoothPlastic or Enum.Material.Neon)
			part.Anchored = true
			part.CanCollide = false
			part.CanQuery = false
			part.CanTouch = false
			part.CastShadow = false
			part.Name = name
			part.Parent = assetsFolder
		else
			note("VFX mesh missing from MoFengVFX: " .. name)
		end
	end
	vfxModel:Destroy()
else
	note("MoFengVFX not found: import MoFengVFX.fbx (or .glb) for slashes, rings, shards and textures, then run this again")
end

-- ---------------------------------------------------------------- the sword

local function tex(key)
	local id = assetsFolder:GetAttribute("Tex_" .. key)
	if typeof(id) == "string" and id ~= "" then
		return id
	end
	local fallbacks = Config.FallbackTextures or {}
	return fallbacks[key] or fallbacks.Default or "rbxasset://textures/particles/sparkles_main.dds"
end

local swordModel = findImport("MoFengSword")
local tool

if swordModel then
	local f = markerFrame(swordModel)
	local parts = {}
	for _, name in ipairs(SWORD_PARTS) do
		parts[name] = findPart(swordModel, name)
		if not parts[name] then
			note("sword part missing: " .. name)
		end
	end
	assert(parts.Handle and parts.BladeEdge, "MoFengSword is missing its Handle or BladeEdge mesh")

	-- 1 Blender unit = 1 stud (the importer may have converted units)
	local factor = LAYOUT.swordScale / f.k
	if math.abs(factor - 1) > 0.01 then
		local all = {}
		for _, p in pairs(parts) do
			table.insert(all, p)
		end
		for _, m in ipairs(f.markers) do
			table.insert(all, m)
		end
		for _, p in ipairs(all) do
			p.Size *= factor
			p.Position = f.O + (p.Position - f.O) * factor
		end
		f = markerFrame(swordModel)
	end

	for _, name in ipairs(TEXTURED) do
		if parts[name] then
			useTextureID(parts[name], name)
			parts[name].Material = Enum.Material.SmoothPlastic
			parts[name].Color = Color3.new(1, 1, 1)
		end
	end
	if parts.Hilt and parts.Hilt.TextureID ~= "" then
		assetsFolder:SetAttribute("Tex_HiltSilver", parts.Hilt.TextureID)
	end
	for name, role in pairs(NEON_ROLES) do
		local p = parts[name]
		if p then
			stripTexture(p)
			p.Material = Enum.Material.Neon
			p.CastShadow = false
			p:SetAttribute("ColorRole", role)
		end
	end
	if parts.BladeAura then
		useTextureID(parts.BladeAura, "BladeAura")
		parts.BladeAura.Material = Enum.Material.ForceField
		parts.BladeAura.CastShadow = false
		parts.BladeAura:SetAttribute("ColorRole", "Primary")
	end

	for _, container in ipairs({ StarterPack, ServerStorage }) do
		local old = container:FindFirstChild(TOOL_NAME)
		if old then
			old:Destroy()
		end
	end
	tool = make("Tool", {
		Name = TOOL_NAME,
		ToolTip = "Click: slash combo  |  E: special",
		CanBeDropped = false,
		RequiresHandle = true,
		Attributes = {
			Theme = Config.DefaultTheme or "Cyan",
			SwordScale = LAYOUT.swordScale,
			BladeHalfWidth = LAYOUT.points.BladeHalfWidth * LAYOUT.swordScale,
		},
	}, nil)
	CollectionService:AddTag(tool, TAG)

	local handle = parts.Handle
	for _, p in pairs(parts) do
		p.Anchored = false
		p.CanCollide = false
		p.CanQuery = false
		p.CanTouch = false
		p.Massless = true
		p.Parent = tool
	end
	for _, p in pairs(parts) do
		if p ~= handle then
			make("WeldConstraint", { Part0 = handle, Part1 = p }, handle)
		end
	end

	-- Grip: hand on the upper grip, blade pointing up the hand's grip axis,
	-- flat of the blade facing forward (what the camera sees in third person).
	local P = LAYOUT.points
	local gripPos = handle.CFrame:PointToObjectSpace(toWorld(f, P.Grip))
	local bladeDir = handle.CFrame:VectorToObjectSpace(f.Z)
	local widthDir = handle.CFrame:VectorToObjectSpace(f.X)
	tool.Grip = CFrame.fromMatrix(gripPos, widthDir, bladeDir)

	local function attach(part, name, point)
		local a = make("Attachment", { Name = name }, part)
		a.WorldCFrame = CFrame.fromMatrix(toWorld(f, point), f.X, f.Z)
		return a
	end
	local edge = parts.BladeEdge
	local hilt = parts.Hilt or handle
	local aBase = attach(edge, "BladeBase", P.BladeBase)
	local aTip = attach(edge, "BladeTip", P.BladeTip)
	attach(edge, "BladeMid", P.BladeMid)
	local aFlow0 = attach(edge, "FlowStart", P.FlowStart)
	local aFlow1 = attach(edge, "FlowEnd", P.FlowEnd)
	local aGuard = attach(hilt, "GuardCenter", P.GuardCenter)
	local aPommel = attach(hilt, "Pommel", P.Pommel)

	local box = Enum.ParticleEmitterShape.Box
	local volume = Enum.ParticleEmitterShapeStyle.Volume
	local surface = Enum.ParticleEmitterShapeStyle.Surface

	-- idle aura: flame wisps licking off the blade
	make("ParticleEmitter", {
		Name = "AuraWisps",
		Texture = tex("Wisp"),
		FlipbookLayout = Enum.ParticleFlipbookLayout.Grid4x4,
		FlipbookMode = Enum.ParticleFlipbookMode.OneShot,
		Rate = 22,
		Lifetime = NumberRange.new(0.55, 0.9),
		Speed = NumberRange.new(0.4, 1.0),
		SpreadAngle = Vector2.new(180, 180),
		Shape = box,
		ShapeStyle = volume,
		Acceleration = Vector3.new(0, 2.5, 0),
		Drag = 3,
		Size = ns({ { 0, 0.15 }, { 0.3, 0.42 }, { 1, 0.1 } }),
		Transparency = ns({ { 0, 1 }, { 0.15, 0.35 }, { 1, 1 } }),
		Rotation = NumberRange.new(-180, 180),
		RotSpeed = NumberRange.new(-90, 90),
		LightEmission = 1,
		LightInfluence = 0,
		ZOffset = 0.3,
		Attributes = { ColorRole = "Primary", ColorRole2 = "Vein", TextureKey = "Wisp", Flipbook = true },
	}, edge)
	-- floating motes drifting upward
	make("ParticleEmitter", {
		Name = "Motes",
		Texture = tex("Ember"),
		Rate = 10,
		Lifetime = NumberRange.new(1.2, 2.2),
		Speed = NumberRange.new(0.1, 0.4),
		SpreadAngle = Vector2.new(180, 180),
		Shape = box,
		ShapeStyle = volume,
		Acceleration = Vector3.new(0, 1.4, 0),
		Size = ns({ { 0, 0.08 }, { 0.5, 0.12 }, { 1, 0 } }),
		Transparency = ns({ { 0, 1 }, { 0.2, 0 }, { 0.8, 0.2 }, { 1, 1 } }),
		LightEmission = 1,
		LightInfluence = 0,
		Attributes = { ColorRole = "Core", ColorRole2 = "Primary", TextureKey = "Ember" },
	}, edge)
	-- burst emitters (Rate 0, fired from scripts)
	make("ParticleEmitter", {
		Name = "SwingSparks",
		Texture = tex("Spark"),
		Orientation = Enum.ParticleOrientation.VelocityParallel,
		Rate = 0,
		Lifetime = NumberRange.new(0.25, 0.45),
		Speed = NumberRange.new(10, 18),
		SpreadAngle = Vector2.new(180, 180),
		Shape = box,
		ShapeStyle = surface,
		Drag = 5,
		Acceleration = Vector3.new(0, -8, 0),
		Size = ns({ { 0, 0.2 }, { 1, 0 } }),
		Transparency = ns({ { 0, 0 }, { 1, 1 } }),
		LightEmission = 1,
		LightInfluence = 0,
		Attributes = { ColorRole = "Core", ColorRole2 = "Primary", TextureKey = "Spark" },
	}, edge)
	make("ParticleEmitter", {
		Name = "Fragments",
		Texture = tex("Star"),
		Rate = 0,
		Lifetime = NumberRange.new(0.4, 0.7),
		Speed = NumberRange.new(6, 11),
		SpreadAngle = Vector2.new(180, 180),
		Shape = box,
		ShapeStyle = volume,
		Drag = 3,
		Acceleration = Vector3.new(0, -12, 0),
		Rotation = NumberRange.new(0, 360),
		RotSpeed = NumberRange.new(-300, 300),
		Size = ns({ { 0, 0.16 }, { 1, 0 } }),
		Transparency = ns({ { 0, 0 }, { 0.8, 0.3 }, { 1, 1 } }),
		LightEmission = 1,
		LightInfluence = 0,
		Attributes = { ColorRole = "Vein", ColorRole2 = "Primary", TextureKey = "Star" },
	}, edge)
	make("ParticleEmitter", {
		Name = "Crackle",
		Texture = tex("Spark"),
		Orientation = Enum.ParticleOrientation.VelocityParallel,
		Rate = 0,
		Lifetime = NumberRange.new(0.15, 0.3),
		Speed = NumberRange.new(3, 6),
		SpreadAngle = Vector2.new(180, 180),
		Shape = box,
		ShapeStyle = surface,
		Size = ns({ { 0, 0.14 }, { 1, 0 } }),
		Transparency = ns({ { 0, 0 }, { 1, 1 } }),
		LightEmission = 1,
		LightInfluence = 0,
		Attributes = { ColorRole = "Core", ColorRole2 = "Vein", TextureKey = "Spark" },
	}, edge)
	-- soft glow around the guard and the pommel gem
	make("ParticleEmitter", {
		Name = "GuardHalo",
		Texture = tex("Glow"),
		Rate = 4,
		Lifetime = NumberRange.new(0.6),
		Speed = NumberRange.new(0),
		LockedToPart = true,
		Size = ns({ { 0, 1.2 }, { 0.5, 1.5 }, { 1, 1.2 } }),
		Transparency = ns({ { 0, 1 }, { 0.3, 0.8 }, { 0.7, 0.8 }, { 1, 1 } }),
		LightEmission = 1,
		LightInfluence = 0,
		ZOffset = -0.5,
		Attributes = { ColorRole = "Primary", TextureKey = "Glow" },
	}, aGuard)
	make("ParticleEmitter", {
		Name = "PommelHalo",
		Texture = tex("Glow"),
		Rate = 4,
		Lifetime = NumberRange.new(0.6),
		Speed = NumberRange.new(0),
		LockedToPart = true,
		Size = ns({ { 0, 0.55 }, { 0.5, 0.7 }, { 1, 0.55 } }),
		Transparency = ns({ { 0, 1 }, { 0.3, 0.7 }, { 0.7, 0.7 }, { 1, 1 } }),
		LightEmission = 1,
		LightInfluence = 0,
		Attributes = { ColorRole = "Accent", TextureKey = "Glow" },
	}, aPommel)
	make("ParticleEmitter", {
		Name = "TipGlint",
		Texture = tex("Star"),
		Rate = 0.8,
		Lifetime = NumberRange.new(0.35),
		Speed = NumberRange.new(0),
		LockedToPart = true,
		Rotation = NumberRange.new(0, 360),
		Size = ns({ { 0, 0 }, { 0.4, 0.7 }, { 1, 0 } }),
		Transparency = ns({ { 0, 0 }, { 1, 0.2 } }),
		LightEmission = 1,
		LightInfluence = 0,
		ZOffset = 0.5,
		Attributes = { ColorRole = "Core", TextureKey = "Star" },
	}, aTip)
	-- swing trails: bright core plus a longer soft glow
	make("Trail", {
		Name = "TrailCore",
		Attachment0 = aBase,
		Attachment1 = aTip,
		Texture = tex("Trail"),
		TextureMode = Enum.TextureMode.Stretch,
		Lifetime = 0.16,
		MinLength = 0.05,
		FaceCamera = false,
		Transparency = ns({ { 0, 0 }, { 1, 1 } }),
		WidthScale = ns({ { 0, 1 }, { 1, 0.6 } }),
		LightEmission = 1,
		LightInfluence = 0,
		Enabled = false,
		Attributes = { ColorRole = "Core", ColorRole2 = "Primary", TextureKey = "Trail" },
	}, edge)
	make("Trail", {
		Name = "TrailGlow",
		Attachment0 = aBase,
		Attachment1 = aTip,
		Texture = tex("Trail"),
		TextureMode = Enum.TextureMode.Stretch,
		Lifetime = 0.28,
		MinLength = 0.05,
		Transparency = ns({ { 0, 0.45 }, { 1, 1 } }),
		LightEmission = 1,
		LightInfluence = 0,
		Enabled = false,
		Attributes = { ColorRole = "Primary", TextureKey = "Trail" },
	}, edge)
	-- energy flowing up the blade, and a soft glow around it
	make("Beam", {
		Name = "FlowBeam",
		Attachment0 = aFlow0,
		Attachment1 = aFlow1,
		Texture = tex("Beam"),
		TextureMode = Enum.TextureMode.Wrap,
		TextureLength = 1.2,
		TextureSpeed = 1.6,
		Width0 = 0.36,
		Width1 = 0.16,
		FaceCamera = true,
		Segments = 10,
		LightEmission = 1,
		LightInfluence = 0,
		Transparency = ns({ { 0, 0.35 }, { 0.5, 0.15 }, { 1, 0.4 } }),
		ZOffset = 0.05,
		Attributes = { ColorRole = "Core", ColorRole2 = "Primary", TextureKey = "Beam" },
	}, edge)
	make("Beam", {
		Name = "GlowBeam",
		Attachment0 = aFlow0,
		Attachment1 = aFlow1,
		Texture = tex("Glow"),
		TextureMode = Enum.TextureMode.Stretch,
		Width0 = 1.0,
		Width1 = 0.55,
		FaceCamera = true,
		LightEmission = 1,
		LightInfluence = 0,
		Transparency = NumberSequence.new(0.78),
		Attributes = { ColorRole = "Primary", TextureKey = "Glow" },
	}, edge)
	make("PointLight", {
		Name = "BladeLight",
		Range = 9,
		Brightness = 1.6,
		Shadows = false,
		Attributes = { ColorRole = "Primary" },
	}, edge)
	make("PointLight", {
		Name = "GemLight",
		Range = 4,
		Brightness = 1.2,
		Shadows = false,
		Attributes = { ColorRole = "Accent" },
	}, aPommel)

	local sounds = Config.Sounds or {}
	for name, loudness in pairs({ Equip = 0.5, Swing = 0.6, Special = 0.8 }) do
		make("Sound", { Name = name .. "Sound", SoundId = sounds[name] or "", Volume = loudness }, handle)
	end

	local s = LAYOUT.swordScale
	if math.abs(s - 1) > 1e-3 then
		for _, d in ipairs(tool:GetDescendants()) do
			if d:IsA("ParticleEmitter") then
				local keys = {}
				for _, kp in ipairs(d.Size.Keypoints) do
					table.insert(keys, NumberSequenceKeypoint.new(kp.Time, kp.Value * s, kp.Envelope * s))
				end
				d.Size = NumberSequence.new(keys)
				d.Speed = NumberRange.new(d.Speed.Min * s, d.Speed.Max * s)
			elseif d:IsA("Beam") then
				d.Width0 *= s
				d.Width1 *= s
			elseif d:IsA("PointLight") then
				d.Range *= s
			end
		end
	end

	for _, m in ipairs(f.markers) do
		m:Destroy()
	end
	swordModel:Destroy()

	tool.Parent = StarterPack
	local copy = tool:Clone()
	copy.Parent = ServerStorage
	local okVfx, SwordVFX = pcall(require, folder:FindFirstChild("SwordVFX"))
	if okVfx then
		SwordVFX.ApplyTheme(tool)
		SwordVFX.ApplyTheme(copy)
	else
		note("could not preview the theme colours in Studio (" .. tostring(SwordVFX) .. "); they apply in game")
	end
	Selection:Set({ tool })
else
	tool = StarterPack:FindFirstChild(TOOL_NAME)
	if tool then
		note("MoFengSword not found, so only the scripts were updated (the existing sword was kept)")
	else
		note("MoFengSword not found: import MoFengSword.fbx (or .glb) with the 3D Importer, then run this again")
	end
end

if recording then
	pcall(function()
		ChangeHistoryService:FinishRecording(recording, Enum.FinishRecordingOperation.Commit)
	end)
end

print(("[Mo Feng] Install finished%s. Sword: %s | Scripts: ReplicatedStorage.MoFengSword, "):format(
	#notes > 0 and (" with " .. #notes .. " note(s) above") or "",
	tool and tool:GetFullName() or "not built"
) .. "ServerScriptService.MoFengSwordServer, StarterPlayerScripts.MoFengSwordClient")
